// Bilinear sample of a grid at fractional post (x, y), clamped to the grid.
export function bilinear(grid, width, height, x, y) {
  const x0 = Math.max(0, Math.min(Math.floor(x), width - 2));
  const y0 = Math.max(0, Math.min(Math.floor(y), height - 2));
  const fx = Math.min(Math.max(x - x0, 0), 1);
  const fy = Math.min(Math.max(y - y0, 0), 1);
  const i = y0 * width + x0;
  const top = grid[i] * (1 - fx) + grid[i + 1] * fx;
  const bottom = grid[i + width] * (1 - fx) + grid[i + width + 1] * fx;
  return top * (1 - fy) + bottom * fy;
}
